\begin{definition}[Execution model]
Execution proceeds in synchronous rounds. Communication is over an unauthenticated diffusion channel $\mathcal{F}_{\mathsf{diff}}$: a message sent by an honest party in round $\rho$ is delivered to every party at the beginning of round $\rho+1$; the adversary chooses the order in which messages arrive at different parties and may send its own messages to an adaptively chosen subset of the parties, so parties cannot tell who sent a message. The adversary is PPT in $\lambda$, is Byzantine, and controls every run-time identity in $\bigcup_i G_i \setminus H$, including the corresponding secret keys. Each honest party $P_i$ starts with input $b_i \in \{0,1\}$, the public parameters $(1^{\lambda}, n_{\max}, m)$, its key pair $(\mathsf{pk}_i, \mathsf{sk}_i)$, its identifier $r_i$, and the set $G_i$; the protocol logic may not depend on $n$ or on network identities.
\end{definition}

\begin{definition}[$(\gamma,\epsilon)$-partial PKI]
An assignment of run-time identities and recognized sets $(G_i)_i$ to the parties of an execution is a \emph{$(\gamma,\epsilon)$-partial PKI} if
\begin{enumerate}
\item $|H \cap G_i| \ge (1-\epsilon)\,|H|$ for every honest $P_i$, and
\item $|H| \ge (1-\gamma)\,\big|\bigcup_i G_i\big|$.
\end{enumerate}
\end{definition}

\begin{definition}[Consensus]
A protocol in which every honest $P_i$ has input $b_i \in \{0,1\}$ and outputs $b_i' \in \{0,1\}$ achieves \emph{consensus} if
\begin{itemize}
\item \textbf{Agreement:} all honest parties output the same bit;
\item \textbf{Validity:} if every honest party has the same input $b$, then every honest party outputs $b$;
\item \textbf{Termination:} every honest party halts with an output.
\end{itemize}
\end{definition}
